+static void counting_sort_pass(uint32_t* src, uint32_t* dst, size_t n, int shift) {
+    uint32_t count[256] = {0};
+
+    // 1. Count frequencies
+    for (size_t i = 0; i < n; ++i) {
+        uint8_t digit = (uint8_t)((src[i] >> shift) & 0xFF);
+        count[digit]++;
+    }
